+  router.get('/books', ({ query }) => {
+    const total = inventory.list().length;
+    // parse page and limit
+    let page = 1;
+    let limit = 20;
+    if (query.has('page')) {
+      const p = parseInt(query.get('page'), 10);
+      if (isNaN(p) || p < 1) {
+        return { status: 400, body: { error: 'Invalid page' } };
+      }
+      page = p;
+    }
+    if (query.has('limit')) {
+      let l = parseInt(query.get('limit'), 10);
+      if (isNaN(l) || l < 1) {
+        return { status: 400, body: { error: 'Invalid limit' } };
+      }
+      if (l > 50) l = 50;
+      limit = l;
+    }
+    const start = (page - 1) * limit;
+    const end = start + limit;
+    const items = inventory.list().slice(start, end);
+    return {
+      status: 200,
+      body: items,
+      headers: { 'X-Total-Count': total.toString() }
+    };
+  })

